# Find all <span class="[^\"]*material-symbols-outlined[^\"]*">\s*([a-z_]+)\s*</span>
def replace_icon(match):
    full_span = match.group(0)
    inner_text = match.group(1).strip()
    if inner_text in icons:
        return icons[inner_text]
    return full_span

content = re.sub(r'<span class="[^\"]*material-symbols-outlined[^\"]*">\s*([a-z_]+)\s*</span>', replace_icon, content)

with open(file_path, 'w', encoding='utf-8') as f:
    f.write(content)

print('Done')
